namespace Icinga\Module\Icingabridge\Controllers;


use Icinga\Application\Config;
use Icinga\Module\Icingabridge\Forms\ModuleconfigForm;
use ipl\Web\Compat\CompatController;

class ModuleconfigController extends CompatController
{


    public function indexAction()
    {
        $form = (new ModuleconfigForm())
            ->setIniConfig(Config::module('icingabridge'));

        $form->handleRequest();

        $this->view->tabs = $this->Module()->getConfigTabs()->activate('config/moduleconfig');
        $this->view->form = $form;
    }


    public function createTabs()
    {
        $tabs = $this->getTabs();

        $tabs->add('icingabridge/config', [
            'label' => $this->translate('Configure Icingabridge'),
            'url' => 'icingabridge/config'
        ]);

        return $tabs;
    }

}